function calculateFormula(formula, sheetData) {
    if (!formula || typeof formula !== 'string' || !formula.startsWith('=')) {
        return null; // Not a formula or empty
    }

    // 1. Clean up the formula string (remove leading '=')
    let cleanFormula = formula.substring(1).trim();

    try {
        // Simple regex to find function calls like SUMA(...)
        const funcMatch = cleanFormula.match(/([A-Z]+)\(([^)]+)\)/i);
        if (!funcMatch) {
            return null; // Not a recognized function format
        }

        const functionName = funcMatch[1].toUpperCase();
        let argumentsString = funcMatch[2];

        // 2. Handle common functions (SUMA, RESTA, MULTIPLICACION, DIVISION)
        if (functionName === 'SUMA') {
            // Summation: A1:A3 or A1;B2;C3
            let values = [];
            const rangesOrCells = argumentsString.split(/[\s:]+/).filter(s => s);

            for (const item of rangesOrCells) {
                if (item.includes(':')) {
                    // Range format: A1:A3
                    const [startCell, endCell] = item.split(':').map(c => c.trim());
                    let startCoords = getCoordinatesFromCellReference(startCell);
                    let endCoords = getCoordinatesFromCellReference(endCell);

                    if (!startCoords || !endCoords) continue;

                    // Assuming same column for simplicity based on typical spreadsheet usage (A1:A3 means A1, A2, A3)
                    const col = startCoords.col;
                    const startRow = Math.min(parseInt(startCoords.row), parseInt(endCoords.row));
                    const endRow = Math.max(parseInt(startCoords.row), parseInt(endCoords.row));

                    for (let r = startRow; r <= endRow; r++) {
                        values.push(sheetData[r - 1][col]); // sheetData is 0-indexed, rows are 1-indexed
                    }
                } else if (item.includes(';')) {
                     // Multiple cells separated by semicolon: A1;B2;C3
                    const individualCells = item.split(';').map(s => s.trim());
                    for (const cellRef of individualCells) {
                        const coords = getCoordinatesFromCellReference(cellRef);
                        if (coords) values.push(sheetData[coords.row - 1][coords.col]);
                    }
                } else {
                    // Single cell reference: A1
                    const coords = getCoordinatesFromCellReference(item);
                    if (coords) values.push(sheetData[coords.row - 1][coords.col]);
                }
            }

            let sum = 0;
            values.forEach(val => {
                // Ensure we only sum numbers, treating empty/non-numeric as 0
                const numVal = parseFloat(val) || 0;
                sum += numVal;
            });
            return sum;

        } else if (functionName === 'RESTA') {
             // Simple subtraction: A1-B1 or SUMA(A1)-SUMA(B1) - but the requirement suggests =A1-B1 style too.
             // Since we are parsing function calls, let's assume it handles multiple arguments separated by commas/semicolons if needed, 
             // but for simplicity based on R3 examples (A1-B1), we might need to handle direct arithmetic later.
             // For now, sticking to the structure: A - B
            let values = [];
            const rangesOrCells = argumentsString.split(/[\s:]+/).filter(s => s);

            if (rangesOrCells.length < 2) return null; // Need at least two operands

            // This is a simplification, assuming the first value minus the rest combined or similar structure.
            // Given the ambiguity of function arguments for simple arithmetic, we'll prioritize direct calculation if possible.
            return parseFloat(values[0]) - parseFloat(values[1]);


        } else if (functionName === 'MULTIPLICACION') {
             let values = [];
            const rangesOrCells = argumentsString.split(/[\s:]+/).filter(s => s);

            if (rangesOrCells.length < 2) return null;
            return parseFloat(values[0]) * parseFloat(values[1]);


        } else if (functionName === 'DIVISION') {
             let values = [];
            const rangesOrCells = argumentsString.split(/[\s:]+/).filter(s => s);

            if (rangesOrCells.length < 2) return null;
            const divisor = parseFloat(values[1]) || 0;
            return divisor === 0 ? 'Error: División por cero' : parseFloat(values[0]) / divisor;
        }

    } catch (e) {
        console.error("Error calculating formula:", e);
        return null;
    }

    return null;
}

/**
 * Helper function to convert cell reference (A1, B2) into 0-indexed coordinates {row: N, col: M}.
 * @param {string} cellRef - The cell reference string.
 * @returns {{row: number, col: number}|null} Coordinates or null if invalid.
 */
function getCoordinatesFromCellReference(cellRef) {
    if (!cellRef || typeof cellRef !== 'string') return null;

    const match = cellRef.match(/([A-Z]+)([1-9]\d*)/i);
    if (!match) return null;

    const colName = match[1].toUpperCase();
    const rowStr = match[2];

    // Convert column letter (A, B, C...) to 0-indexed number (0, 1, 2...)
    let colIndex = 0;
    for (let i = 0; i < colName.length; i++) {
        colIndex = colIndex * 26 + (colName.charCodeAt(i) - 'A'.charCodeAt(0) + 1);
    }
    const col = colIndex - 1; // Convert 1-based index to 0-based

    const row = parseInt(rowStr);

    if (isNaN(row) || isNaN(col)) return null;

    return { row: row, col: col };
}
