function calculateFormula(formulaString, sheetData) {
    if (!formulaString || !formulaString.startsWith('=')) {
        return formulaString; // Not a formula or empty
    }

    // 1. Clean the formula string (remove leading '=')
    let expression = formulaString.substring(1).trim();

    try {
        // 2. Replace cell references (e.g., A1, B2) with their actual values
        // Regex: Matches a single uppercase letter followed by one or more digits (A1, J20)
        expression = expression.replace(/([A-Z]+)(\d+)/g, (match, colStr, rowNumStr) => {
            let colIndex = getColumnIndex(colStr);
            let rowIndex = parseInt(rowNumStr) - 1; // Convert 1-based to 0-based

            // Check if the coordinates are valid and data exists in sheetData
            if (colIndex >= 0 && colIndex < sheetData.columns.length && rowIndex >= 0 && rowIndex < sheetData.rows.length) {
                let cellValue = sheetData.rows[rowIndex][colIndex];
                // Ensure the value is treated as a number if possible, otherwise keep it as string/text
                const numericValue = typeof cellValue === 'number' ? cellValue : parseFloat(cellValue);
                return isNaN(numericValue) ? `'${cellValue}`` : numericValue; // Use quotes for non-numeric strings in evaluation context
            } else {
                // If reference is invalid, treat it as an error string
                return 'ERROR';
            }
        });

        // 3. Evaluate the resulting mathematical expression
        // Using Function constructor for safe evaluation scope (safer than eval())
        const calculator = new Function(`return ${expression}`);
        let result = calculator();

        // Handle potential NaN results from calculation
        if (isNaN(result) || !isFinite(result)) {
            return 'ERROR';
        }

        // Return the calculated value, formatted as a string for display
        return String(result);

    } catch (e) {
        console.error("Formula evaluation error:", e);
        return '#ERROR!'; // Display standard Excel error message
    }
}
