            calculatedValue = rawInput;
        }

        // Update the visible element content
        element.textContent = calculatedValue;

        // Update the internal model (sheetData)
        if (!sheetData.rows[rowNum - 1]) {
            sheetData.rows[rowNum - 1] = new Array(MAX_COLS).fill('');
        }
        let colIndex = getColumnIndex(colStr);
