    function recalculateDependentCells(changedRowNum, changedColStr) {
        // 1. Check the entire row for formulas (A -> J)
        for (let j = 0; j < MAX_COLS; j++) {
            const colStr = String.fromCharCode(65 + j);
            if (colStr !== changedColStr) { // Skip the cell that was just updated
