            // Attempt to parse the content as a number if it looks like one, otherwise use string value
            const text = cellElement.textContent.trim();
            return isNaN(parseFloat(text)) ? `'${text}'` : parseFloat(text);
        }
        return '0'; // Default if reference is invalid or empty
    });

    // 3. Evaluate the resulting mathematical expression using Function constructor (safer than eval)
    try {
        // Handle Excel function names and translate them to JS equivalents
        let jsFormula = formula
            .replace(/SUMA\(([^)]+)\)/g, 'Math.sum([$1].split(';').map(s => parseFloat(s.trim()))))') // Simplified SUMA handling for ranges/lists
            // Basic arithmetic operators are already handled by the replacement above if they were simple references (e.g., A1-B1)

        // For simplicity and robustness in this context, we will rely on JS's ability to evaluate basic math operations 
        // after replacing cell references with numbers/strings.

        // Since complex array handling is difficult without a full parser, let's focus on the core arithmetic:
        let finalExpression = formula;

        // Simple replacement for common functions (SUMA) - assuming ranges are comma-separated in JS context
        if (finalExpression.toUpperCase().startsWith('SUMA')) {
             const rangeMatch = finalExpression.match(/SUMA\(([^)]+)\)/i);
             if (rangeMatch && rangeMatch[1]) {
                 // Assuming the input format is A1:A3 or A1;B2;C3
                 let cellsToSum = [];
                 const parts = rangeMatch[1].split(/[:;]/).map(p => p.trim());

                 if (parts.length > 0) {
                     // If it's a single cell reference, treat it as an array of one element for consistency
                     let references = parts.filter(p => p);

                     // Get values from the DOM based on references
                     references.forEach(ref => {
                         const value = getCellValueFromReference(ref);
                         if (value !== null) cellsToSum.push(value);
                     });

                     return cellsToSum.reduce((acc, val) => acc + parseFloat(val), 0).toFixed(2);
                 }
             }
        }


        // If it's not a recognized function or if the formula is simple arithmetic (A1-B1):
        const result = Function(`return ${finalExpression}`)();

        if (isNaN(result)) {
            return "Error"; // Handle calculation errors
        }
        return parseFloat(result).toFixed(2);

    } catch (e) {
        console.error("Formula evaluation error:", e);
        return "#ERROR!"; // Display a clear error message
    }
}
