### FUNCION: getCellValueFromReference
```javascript
function getCellValueFromReference(ref) {
    const match = ref.match(/([A-Z]+)([0-9]+)/i);
    if (!match) return null;

    const colLetter = match[1].toUpperCase();
    const rowNumber = parseInt(match[2]);

    // Calculate column index (A=0, B=1, ...)
    let colIndex = 0;
    for (let i = 0; i < colLetter.length; i++) {
        colIndex = colIndex * 26 + (colLetter.charCodeAt(i) - 'A'.charCodeAt(0) + 1);
    }
    // Adjust to 0-based index for array access if needed, but here we use it for data attributes

    const cellElement = document.querySelector(`td[data-row="${rowNumber}"][data-col="${colLetter}"]`);
    if (cellElement) {
        let textContent = cellElement.textContent.trim();
        // If the content is a number, return the float value for calculation purposes
        return !isNaN(parseFloat(textContent)) ? parseFloat(textContent) : textContent;
    }
    return null;
}
