### FUNCION: calculateAllFormulas
```js
function calculateAllFormulas() {
    const rows = document.querySelectorAll('#spreadsheet-container tbody tr');
    const cols = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];

    // 1. Recolectar todos los valores de la hoja (incluyendo fórmulas)
    let sheetData = {}; // { row: { col: value } }

    rows.forEach(row => {
        const rowNum = parseInt(row.dataset.row);
        sheetData[rowNum] = {};
        cols.forEach(colName => {
            const cell = row.querySelector(`[data-col="${colName}"]`);
            if (cell) {
                // Guardamos el valor tal cual está en el DOM, ya sea número, texto o fórmula
                sheetData[rowNum][colName] = cell.textContent.trim();
            }
        });
    });

    // 2. Iterar sobre todas las celdas para evaluar fórmulas
    rows.forEach(row => {
        const rowNum = parseInt(row.dataset.row);
        cols.forEach(colName => {
            const cell = row.querySelector(`[data-col="${colName}"]`);

            if (cell && typeof cell.textContent === 'string' && cell.textContent.trim().startsWith('=')) {
                let formulaString = cell.textContent.trim();
                let result = evaluateFormula(formulaString, sheetData);

                // Actualizar el contenido visible de la celda con el resultado calculado
                cell.textContent = (result === null || isNaN(result)) ? "" : result;
            } else if (cell && !isNaN(parseFloat(cell.textContent.trim())) && cell.textContent.trim() !== "") {
                 // Si es un número puro, asegurarse de que se muestre como tal si no hay fórmula
                cell.textContent = parseFloat(cell.textContent.trim()).toString();
            }
        });
    });
}
```

### FUNCION: evaluateFormula
```js
function evaluateFormula(formulaString, sheetData) {
    try {
        // 1. Reemplazar referencias de columna y fila (ej: B1 -> sheetData[1]['B'])
        let processedFormula = formulaString;
        const regex = /([A-Z]+)(\d+)/g; // Captura Columna(A-Z) y Fila(\d+)

        processedFormula = processedFormula.replace(regex, (match, colName, rowNumStr) => {
            const rowNum = parseInt(rowNumStr);
            let value = null;

            // Intentar obtener el valor de la celda referenciada en sheetData
            if (sheetData[rowNum] && sheetData[rowNum][colName]) {
                let cellValue = sheetData[rowNum][colName];
                // Si el valor es una fórmula, debe ser evaluado primero para obtener su resultado numérico.
                // Esto requiere recursividad o un manejo más complejo del estado, pero por simplicidad, 
                // asumiremos que si está en sheetData, ya fue calculado previamente o es un valor base.
                if (cellValue.startsWith('=')) {
                    // Si la referencia apunta a una fórmula, necesitamos su resultado numérico.
                    // Para este scope limitado, simplemente lo trataremos como el texto de la fórmula 
                    // y dejaremos que eval() maneje la evaluación si es posible, o asumiremos que los valores base son números.
                }
                value = cellValue;
            }

            // Devolver una cadena que JavaScript pueda evaluar (ej: '10' en lugar de B1)
            return JSON.stringify(value); 
        });

        // 2. Evaluar la fórmula resultante usando eval() o Function constructor
        // Usamos new Function para evitar problemas de scope con eval() directo.
        const calculator = new Function(`return (${processedFormula})`);
        let result = calculator();

        // Si el resultado es un string que parece número, lo convertimos a float/int
        if (typeof result === 'string' && !isNaN(parseFloat(result))) {
            return parseFloat(result);
        }
        return result;

    } catch (e) {
        console.error("Error evaluating formula:", e);
        return null; // Retorna null si la fórmula es inválida
    }
}
