### script.js
```javascript
document.addEventListener('DOMContentLoaded', () => {
    const spreadsheetContainer = document.getElementById('spreadsheet-container');
    const cells = spreadsheetContainer.querySelectorAll('.data-cell');

    // --- Initialization Functions ---

    /**
     * Inicializa la estructura de las filas y columnas en el DOM.
     */
    function initializeSpreadsheet() {
        const tbody = spreadsheetContainer.querySelector('tbody');
        if (!tbody) return;

        // Limpiar contenido existente para evitar duplicaciones si se llama varias veces
        tbody.innerHTML = ''; 

        for (let i = 1; i <= 20; i++) {
            const row = document.createElement('tr');
            row.id = `row-header-${i}`;

            // Columna de índice de fila
            const indexCell = document.createElement('td');
            indexCell.className = 'row-index';
            indexCell.textContent = i;
            row.appendChild(indexCell);

            for (let j = 0; j < 10; j++) {
                const colName = String.fromCharCode(65 + j); // A, B, C...
                const cell = document.createElement('td');
                cell.setAttribute('data-row', i);
                cell.setAttribute('data-col', colName);
                cell.className = 'data-cell';
                cell.contentEditable = true;
                // Añadir un listener de input para manejar los cambios en tiempo real
                cell.addEventListener('input', handleCellInput); 
                row.appendChild(cell);
            }
            tbody.appendChild(row);
        }

        // Inicializar listeners globales después de generar todas las celdas
        setupEventListeners();
    }

    /**
     * Configura los event listeners para los controles de la hoja de cálculo.
     */
    function setupEventListeners() {
        const controls = document.getElementById('controls');
        if (!controls) return;

        // Listener general para cualquier cambio en las celdas (input/blur)
        spreadsheetContainer.addEventListener('input', handleCellInput);
        spreadsheetContainer.addEventListener('blur', handleCellInput);


        document.getElementById('btn-delete-column').addEventListener('click', deleteColumn);
        document.getElementById('btn-clear-data').addEventListener('click', clearSelectedData);
        document.getElementById('btn-hide-row').addEventListener('click', hideRow);
        document.getElementById('btn-show-row').addEventListener('click', showRow);
        document.getElementById('btn-delete-row').addEventListener('click', deleteRow);
        document.getElementById('btn-clear-column').addEventListener('click', clearColumn);
        document.getElementById('btn-hide-col').addEventListener('click', hideCol);
        document.getElementById('btn-show-col').addEventListener('click', showCol);

        // Inicializar el estado de los botones y la hoja
        updateControlStates();
    }


    // --- Event Handlers ---

    /**
     * Maneja cualquier evento de input o blur en una celda de datos.
     * Esto es crucial para disparar el recálculo de fórmulas.
     */
    function handleCellInput(e) {
        const target = e.target;
        if (!target || !target.classList.contains('data-cell')) return;

        // Pequeño retraso para asegurar que el DOM ha actualizado el contenido después del input/blur
        setTimeout(() => {
            recalculateAllFormulas();
            updateControlStates();
        }, 50); // Retraso de 50ms para estabilidad en la recálculo

    }


    // --- Formula and Calculation Logic ---

    /**
     * Obtiene el valor numérico o string de una celda, manejando fórmulas.
     * @param {HTMLElement} cellElement - El elemento TD de la celda.
     * @returns {string|number} El valor calculado o el contenido si no es fórmula.
     */
    function getCellValue(cellElement) {
        let content = cellElement.textContent.trim();

        if (content.startsWith('=')) {
            // Si contiene una fórmula, su valor real debe ser recalculado y devuelto como string/number
            return calculateFormulaValue(content);
        } else if (!isNaN(parseFloat(content)) && isFinite(content)) {
            // Es un número puro
            return parseFloat(content);
        }
        // Es texto o vacío
        return content;
    }

    /**
     * Evalúa una fórmula de hoja de cálculo.
     * @param {string} formula - La cadena de la fórmula (ej: "=B1+C1").
     * @returns {number|string} El resultado calculado.
     */
    function calculateFormulaValue(formula) {
        try {
            // 1. Reemplazar referencias de celda (A1, B2, etc.) por sus valores reales.
            let processedFormula = formula;

            // Regex para encontrar patrones como A1, B20, etc. (Letra + Número)
            const cellRefRegex = /([A-Z]+)(\d+)/g; 

            processedFormula = processedFormula.replace(cellRefRegex, (match, colLetters, rowNumStr) => {
                // Encontrar la celda real en el DOM usando data attributes
                const targetRow = parseInt(rowNumStr);
                const targetColName = colLetters[0]; // Solo consideramos la primera letra por simplicidad de ejemplo

                // Buscar la celda específica (data-row y data-col)
                const cellSelector = `[data-row="${targetRow}"][data-col="${targetColName}"]`;
                const targetCell = document.querySelector(cellSelector);

                if (targetCell && targetCell.classList.contains('data-cell')) {
                    // Obtener el valor actual de la celda objetivo
                    let value = getCellValue(targetCell); 
                    return typeof value === 'string' ? `'${value}'` : value; // Envolver strings en comillas para eval
                } else {
                    console.warn(`Celda referencia no encontrada: ${match}`);
                    return match; // Devolver la referencia si no se encuentra
                }
            });

            // 2. Evaluar la fórmula procesada (ej: "4 + 5")
            // Usamos eval con precaución, pero es necesario para simular el comportamiento de las fórmulas.
            const result = eval(processedFormula);

            if (isNaN(result) || !isFinite(result)) {
                return "#ERROR!";
            }
            return result;

        } catch (e) {
            console.error("Error al calcular la fórmula:", e);
            return "#ERROR!";
        }
    }


    /**
     * Recalcula todas las fórmulas en la hoja de cálculo y actualiza el DOM.
     */
    function recalculateAllFormulas() {
        const allCells = document.querySelectorAll('.data-cell');

        allCells.forEach(cell => {
            let content = cell.textContent.trim();

            if (content.startsWith('=')) {
                // Es una celda de fórmula, recalcular y actualizar el valor visible
                const calculatedValue = calculateFormulaValue(content);

                // Actualizar el contenido editable con el resultado calculado
                cell.textContent = ''; // Limpiar para forzar la actualización del DOM
                cell.setAttribute('data-calculated', 'true'); // Marcar como calculado
                cell.textContent = String(calculatedValue);

            } else {
                // Es una celda de datos, limpiar el atributo de cálculo si existía
                cell.removeAttribute('data-calculated');
            }
        });
    }


    // --- Utility Functions (Control Management) ---

    /**
     * Obtiene la referencia del rango seleccionado actualmente.
     * @returns {{row: number, col: string}|null} Coordenadas o null si nada está seleccionado.
     */
    function getSelectedCellCoords() {
        const selected = document.activeElement;
        if (selected && selected.classList.contains('data-cell')) {
            return { 
                row: parseInt(selected.dataset.row), 
                col: selected.dataset.col 
            };
        }
        return null;
    }

    /**
     * Actualiza el estado de los botones de control (habilitar/deshabilitar).
     */
    function updateControlStates() {
        const coords = getSelectedCellCoords();
        const isDataCell = !!coords;

        // Habilitar/Deshabilitar acciones basadas en la selección
        document.getElementById('btn-delete-column').disabled = !isDataCell;
        document.getElementById('btn-clear-data').disabled = !isDataCell;
        document.getElementById('btn-hide-row').disabled = !isDataCell;
        document.getElementById('btn-show-row').disabled = true; // Siempre se maneja por el estado de la fila

        document.getElementById('btn-delete-row').disabled = !isDataCell;
        document.getElementById('btn-clear-column').disabled = !isDataCell;
        document.getElementById('btn-hide-col').disabled = !isDataCell;
        document.getElementById('btn-show-col').disabled = true; // Siempre se maneja por el estado de la columna

        // Lógica simple para mostrar/ocultar botones (ejemplo: si estamos en una fila, podemos borrarla)
        const rowHeader = document.querySelector('.row-index');
        if (rowHeader && !document.getElementById('btn-delete-row').disabled) {
             // Si se puede borrar la fila, asumimos que el botón de mostrar está oculto o no es relevante aquí.
        }

    }


    /**
     * Borra los datos del rango seleccionado.
     */
    function clearSelectedData() {
