```js
function calculateFormula(cellElement) {
    const formula = cellElement.textContent;
    if (!formula || !formula.startsWith('=')) return false;

    // 1. Extract the formula string (e.g., "=B1+C1")
    let formulaString = formula.substring(1);

    // 2. Get all cells in the spreadsheet container
    const cells = document.querySelectorAll('.spreadsheet-container td');
    let replacements = {};

    // 3. Replace cell references (e.g., B1, C1) with their actual values
    for (const cell of cells) {
        const text = cell.textContent;
        if (text && !isNaN(parseFloat(text))) {
            // Use a regex to find potential cell references like A1, B2, etc.
            // This assumes standard column/row notation and that the value is numeric.
            const matches = [...text.matchAll(/([A-Z]+)(\d+)/g)];
            for (const match of matches) {
                let ref = `${match[1]}${match[2]}`;
                // Store the actual text content of the cell corresponding to the reference
                replacements[ref] = cell.textContent;
            }
        }
    }

    // 4. Perform replacements in the formula string
    for (const ref in replacements) {
        // Escape regex special characters in replacement values
        let value = replacements[ref].toString().replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        // Use global regex to replace all occurrences of the reference
        formulaString = formulaString.replace(new RegExp(ref, 'g'), `(${value})`);
    }

    try {
        // 5. Evaluate the resulting mathematical expression
        const result = eval(formulaString);
        cellElement.textContent = result;
        return true;
    } catch (e) {
        console.error("Error calculating formula:", e);
        return false;
    }
}
