function deleteColumn() {
    const selectedColLetter = document.querySelector('.selected-column')?.dataset.letter;
    if (!selectedColLetter) {
        alert("Por favor, selecciona una columna primero.");
        return;
    }

    if (!confirm(`¿Estás seguro de que deseas eliminar la columna ${selectedColLetter}? Esta acción es irreversible.`)) {
        return;
    }

    // 1. Identificar el índice de la columna a borrar (A=0, B=1, ...)
    let columnIndex = -1;
    for (let i = 0; i < selectedColLetter.length; i++) {
        if (selectedColLetter[i].toUpperCase() === String.fromCharCode('A'.charCodeAt(0) + i)) {
            columnIndex = i;
            break;
        }
    }

    if (columnIndex === -1) {
        console.error("Error al determinar el índice de la columna.");
        return;
    }

    // 2. Iterar sobre todas las filas y eliminar la celda en el índice correcto
    const rows = document.querySelectorAll('.spreadsheet-container tr');
    rows.forEach(row => {
        const cellsInRow = row.querySelectorAll('td');
        if (cellsInRow.length > columnIndex) {
            // Eliminar el elemento <td> específico de la columna
            cellsInRow[columnIndex].remove();
        }
    });

    // 3. Limpiar selección y actualizar UI
    document.querySelector('.selected-column')?.classList.remove('selected-column');
    document.querySelector('.selected-column')?.removeAttribute('data-letter');
    alert(`Columna ${selectedColLetter} eliminada exitosamente.`);
}
