function initializeSpreadsheet() {
    // 1. Setup initial structure (Headers and Rows)
    const container = document.getElementById('spreadsheet-container');
    const table = container.querySelector('table');
    const theadRow = table.querySelector('thead tr');
    const tbody = table.querySelector('tbody');

    // Clear existing content to ensure clean initialization if run multiple times
    theadRow.innerHTML = '';
    tbody.innerHTML = '';

    // Add column headers (A-J) and row index header
    let headerHtml = '<th class="row-index-header"></th>'; // Empty corner cell
    for (let i = 0; i < 10; i++) {
        const colName = String.fromCharCode(65 + i); // A, B, C...
        headerHtml += `<th data-col-name="${colName}">${colName}</th>`;
    }
    theadRow.innerHTML = headerHtml;

    // Generate 20 rows (1 to 20)
    for (let r = 1; r <= 20; r++) {
        const row = document.createElement('tr');
        row.id = `row-header-${r}`;

        // Row Index Cell
        let indexCell = document.createElement('td');
        indexCell.className = 'row-index';
        indexCell.textContent = r;
        row.appendChild(indexCell);

        // Data Cells (A to J)
        for (let c = 0; c < 10; c++) {
            const colName = String.fromCharCode(65 + c);
            const cell = document.createElement('td');
            cell.setAttribute('data-row', r);
            cell.setAttribute('data-col', colName);
            cell.setAttribute('contenteditable', 'true');
            cell.id = `cell-${r}-${colName}`; // Unique ID for easy access
            row.appendChild(cell);
        }
        tbody.appendChild(row);
    }

    // 2. Attach Event Listeners
    attachEventListeners();

    // 3. Load State from Local Storage (R9 Fix)
    loadStateFromLocalStorage();
}
