```javascript
function calculateFormula(cellElement) {
    const content = cellElement.textContent.trim();
    if (!content || !content.startsWith('=')) {
        return null; // Not a formula or empty
    }

    // Simple parsing for SUMA(A1;B1) format
    try {
        let formulaString = content.substring(1); // Remove '='
        const match = formulaString.match(/([A-Z]+)\(([^)]+)\)/i);

        if (!match) return null;

        const functionName = match[1].toUpperCase();
        const argsString = match[2];
        // Split arguments by semicolon, handling potential spaces
        const argRefs = argsString.split(';').map(ref => ref.trim());

        let result = null;

        if (functionName === 'SUMA') {
            let sum = 0;
            for (const ref of argRefs) {
                // Expecting references like A1, B2, etc.
                const coordsMatch = ref.match(/([A-Z]+)([0-9]+)/i);
                if (coordsMatch) {
                    const colChar = coordsMatch[1].toUpperCase();
                    const rowNum = parseInt(coordsMatch[2]);

                    // Find the cell element corresponding to the reference
                    const targetCell = document.querySelector(`[data-row="${rowNum}"][data-col="${colChar}"]`);
                    if (targetCell) {
                        let value = targetCell.textContent.trim();
                        // Attempt to parse as number, otherwise treat as 0 for summation
                        value = isNaN(parseFloat(value)) ? parseFloat(value) || 0 : parseFloat(value);
                        sum += value;
                    }
                }
            }
            result = sum;
        } else {
            // Handle other functions if necessary, but only SUMA is required for the fix.
            return null;
        }

        if (result !== null) {
            return result;
        }
    } catch (e) {
        console.error("Error calculating formula:", e);
        return null;
    }
    return null;
}
