```js
function calculateFormula(cellElement) {
    let formula = cellElement.innerText;

    if (!formula || !formula.startsWith('=')) {
        return null; // No formula or empty
    }

    // 1. Clean up the formula string (e.g., replace semicolons with commas if needed for JS eval)
    // Assuming the formulas use standard JavaScript math operators and cell references A1, B2 etc.
    let cleanedFormula = formula.substring(1).replace(/;/g, ',');

    // 2. Get all cell values in the scope of the formula (A1:J20)
    const sheet = document.getElementById('spreadsheet-container');
    const rows = sheet.querySelectorAll('tbody tr');
    const cols = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];

    // Create a map of coordinates to values for easy lookup during evaluation
    let scopeValues = {};
    rows.forEach(row => {
        const rowData = {};
        cols.forEach(colName => {
            const cell = row.querySelector(`[data-col="${colName}"]`);
            if (cell) {
                // Use innerText to get the displayed value, which might be a formula result or text/number
                let value = cell.innerText;
                try {
                    // Attempt to parse as number if possible, otherwise keep string
                    value = isNaN(parseFloat(value)) ? String(value) : parseFloat(value);
                } catch (e) {
                    // Keep original value if parsing fails
                }
                rowData[colName] = value;
            }
        });
        scopeValues[`${row.dataset.row}`] = rowData;
    });

    // 3. Replace cell references (A1, B2, etc.) in the formula string with actual values
    let evaluatedFormula = cleanedFormula;

    // Regex to find patterns like A1, C5, J10 (Letter followed by number)
    const cellRefRegex = /([A-Z]+)(\d+)/g;

    evaluatedFormula = evaluatedFormula.replace(cellRefRegex, (match, colName, rowNumStr) => {
        // Row numbers are 1-indexed in the UI/data attributes
        let rowIndex = parseInt(rowNumStr);
        if (scopeValues[rowIndex] && scopeValues[rowIndex][colName] !== undefined) {
            let value = scopeValues[rowIndex][colName];
            // Ensure we replace with a string representation of the number/value
            return typeof value === 'number' ? value : `'${String(value).replace(/'/g, "\\'")}'`;
        }
        // If reference is invalid or empty, treat it as 0 or an error placeholder
        return '0';
    });

    try {
        // Use Function constructor for safer evaluation context than raw eval()
        const calculator = new Function(`return ${evaluatedFormula}`);
        let result = calculator();

        // Handle potential NaN results from calculation
        if (isNaN(result) || !isFinite(result)) {
            return "Error"; // Or handle specific error display
        }
        return String(result);

    } catch (e) {
        console.error("Formula evaluation error:", e);
        return "#ERROR!"; // Display an explicit error if calculation fails
    }
}
