    }

    // Regex to find references like A1, B2, etc., inside the formula string
    const referenceRegex = /([A-Z]+[0-9]+)/g;
    let matches = [...formula.matchAll(referenceRegex)];

    if (matches.length === 0) {
        return false; // Formula but no references found
    }

    try {
        // Step 1: Get values of referenced cells
        let cellValues = {};
        for (const match of matches) {
            const reference = match[0]; // e.g., A1
            const row = parseInt(reference.substring(1));
            const colName = reference.substring(0, 1).toUpperCase();

            // Find the actual cell element corresponding to the reference (A1 in the current sheet state)
            let targetCell = document.querySelector(`[data-row="${row}"][data-col="${colName}"]`);
            if (targetCell && targetCell.getAttribute('contenteditable') === 'true') {
                // Use textContent, assuming it holds the numerical value if not a formula itself
                const content = targetCell.textContent;
                cellValues[reference] = parseFloat(content) || 0;
            } else {
                 cellValues[reference] = 0;
            }
        }

        // Step 2: Evaluate the formula (Handling SUMA(A1;B1))
        let evaluatedFormula = formula.toUpperCase();

        // Replace function names and arguments with JavaScript equivalents/values
