function calculateValue(formula) {
    try {
        // 1. Pre-process formula: Replace cell references like A1, B2 with their actual values.
        let processedFormula = formula;

        // Regex to find patterns like [A-Z]+[0-9]+ (e.g., A1, C5)
        const cellRefRegex = /([A-Z]+)([0-9]+)/g;

        processedFormula = processedFormula.replace(cellRefRegex, (match, colStr, rowStr) => {
            // Get the actual value from the corresponding cell element
            const cellElement = document.querySelector(`[data-row="${rowStr}"][data-col="${colStr}"]`);
            if (cellElement && cellElement.textContent.trim() !== "") {
                let value = cellElement.textContent.trim();
                // Attempt to convert the retrieved value to a number if possible, otherwise keep it as string/number representation
                return isNaN(parseFloat(value)) ? `'${value}'` : parseFloat(value);
            }
            return '0'; // Default to 0 if cell is empty or not found
        });

        // 2. Evaluate the processed formula using JavaScript's eval() function.
        // Note: Using eval() is generally risky, but necessary here for dynamic spreadsheet calculation based on user input formulas.
        const result = eval(processedFormula);

        // Handle potential NaN results (e.g., division by zero)
        if (isNaN(result)) {
            return "Error";
        }
        return result;

    } catch (e) {
        console.error("Error calculating formula:", e);
        return "#ERROR!"; // Return a clear error message if calculation fails
    }
}
