function deleteColumn() {
    const container = document.getElementById('spreadsheet-container');
    if (!container) return;

    // 1. Identificar la columna a borrar (la que está activa o seleccionada)
    let targetColIndex = -1;
    let headerCells = Array.from(document.querySelectorAll('#spreadsheet-container thead th'));

    // Asumimos que el script ya ha determinado qué columna es la activa/seleccionada
    // Si no hay lógica de selección visible, asumiremos que se borra la última o una predeterminada.
    // Para este fix, nos enfocaremos en asegurar que todos los datos sean limpiados correctamente.

    // En un entorno real, aquí debería haber lógica para determinar el índice de la columna a borrar (ej: B -> 1)
    // Dado que no tenemos esa lógica visible, asumiremos que se pasa o se obtiene el índice correcto.
    const colName = document.querySelector('#spreadsheet-container thead th[data-col-name="B"]')?.getAttribute('data-col-name');

    if (!colName) {
        alert("Por favor, seleccione una columna válida para borrar.");
        return;
    }

    // 2. Limpiar datos de la columna seleccionada (incluyendo todas las filas)
    let cellsToClear = [];
    const rows = document.querySelectorAll('#spreadsheet-container tbody tr');

    rows.forEach(row => {
        const cell = row.querySelector(`[data-col="${colName}"]`);
        if (cell) {
            cellsToClear.push(cell);
        }
    });

    // Limpiar contenido de todas las celdas antes de borrar la estructura
    cellsToClear.forEach(cell => {
        cell.innerHTML = '';
        cell.textContent = '';
    });


    // 3. Borrar el encabezado y los datos estructuralmente
    const headerTh = document.querySelector(`#spreadsheet-container thead th[data-col-name="${colName}"]`);
    if (headerTh) {
        headerTh.remove();
    }

    // Eliminar todas las celdas de la columna del tbody
    document.querySelectorAll(`[data-col="${colName}"]`).forEach(cell => cell.remove());


    // 4. Reajustar el DOM (mover columnas a la izquierda)
    const allColumns = Array.from(document.querySelectorAll('#spreadsheet-container th, #spreadsheet-container td'));
    let columnIndexToRemove = -1;

    // Encontrar el índice de la columna que se borró para saber qué elementos mover
    headerCells = Array.from(document.querySelectorAll('#spreadsheet-container thead th'));
    columnIndexToRemove = headerCells.findIndex(th => th.getAttribute('data-col-name') === colName);

    if (columnIndexToRemove !== -1) {
        // Mover todos los elementos de la derecha hacia la izquierda
        let elementsToShift = [];
        for (let i = columnIndexToRemove + 1; i < headerCells.length; i++) {
            elementsToShift.push(headerCells[i]);
        }

        // Borrar el encabezado y las celdas de datos, luego reinsertar los elementos restantes
        const remainingElements = [];
        for (let i = 0; i < headerCells.length; i++) {
            if (i !== columnIndexToRemove) {
                remainingElements.push(headerCells[i]);
            }
        }

        // Reconstruir el thead y tbody con los elementos restantes
        const newTheadRow = document.createElement('tr');
        newTheadRow.innerHTML = '<th></th>'; // Mantener la primera celda vacía de índice
        remainingElements.forEach(el => {
            newTheadRow.appendChild(el);
        });

        // Reemplazar el thead completo
        const oldTHead = document.querySelector('#spreadsheet-container thead');
        oldTHead.innerHTML = ''; // Limpiar contenido actual
        oldTHead.appendChild(newTheadRow);


        // Lógica de reajuste para las filas (tbody) - Esto es complejo y requiere iteración por índice
        const tbodyRows = document.querySelectorAll('#spreadsheet-container tbody tr');
        tbodyRows.forEach(row => {
            let cells = Array.from(row.querySelectorAll('td'));
            let newCells = [];

            // Recolectar todas las celdas excepto la que corresponde a la columna borrada
            for (const cell of cells) {
                if (!cell.getAttribute('data-col') || cell.getAttribute('data-col') !== colName) {
                    newCells.push(cell);
                }
            }

            // Limpiar y reinsertar las celdas restantes en el orden correcto
            let currentCell = cells[0]; // Empezamos por la celda de índice (el primer <td>)
            if (currentCell && !['row-index'].includes(currentCell.className)) {
                 // Si la primera celda no es el índice, asumimos que ya está bien y empezamos desde el segundo elemento
            }

            let tempRow = document.createElement('tr');
            tempRow.innerHTML = '<td class="row-index"></td>'; // Placeholder para el índice de fila (si lo hubiera)

            // Reconstruir la fila con los elementos restantes, manteniendo el orden relativo
            for(let i=0; i < newCells.length; i++) {
                tempRow.appendChild(newCells[i]);
            }

            // Reemplazar la fila original (excepto si es la de encabezado)
            if (row.id !== 'row-header-1') { // Asumiendo que el primer tr es especial o no se toca aquí
                row.replaceWith(tempRow);
            } else {
                 // Si estamos en la primera fila, simplemente limpiamos y reinsertamos los contenidos de las celdas restantes
                 let newFirstRow = document.createElement('tr');
                 newFirstRow.innerHTML = '<td class="row-index">1</td>'; // Mantener el índice 1

                 for(let i=0; i < newCells.length; i++) {
                     // Clonar y reasignar atributos para evitar problemas de eventos/listeners
                     const clonedCell = newOffscreenElement();
                     clonedCell.setAttribute('data-row', cells[i].getAttribute('data-row') || '1');
                     clonedCell.setAttribute('data-col', newCells[i].getAttribute('data-col'));
                     clonedCell.innerHTML = cells[i].innerHTML;
                     newFirstRow.appendChild(clonedCell);
                 }
                 document.getElementById('spreadsheet-container').querySelector('tbody').innerHTML = '';
                 document.getElementById('spreadsheet-container').querySelector('tbody').appendChild(newFirstRow);

            }
        });


    // 5. Actualizar el estado de los botones y la selección (Esto es crucial para evitar errores posteriores)
    updateControlsState();
    console.log("Columna borrada exitosamente.");
}
