/**
 * ==================================================
 * CORE SETUP AND INITIALIZATION
 * ==================================================
 */

// Helper function to create a temporary element for cloning content safely
function newOffscreenElement() {
    return document.createElement('div'); // Using div as fallback, ideally OffscreenCanvas or similar if available
}


/**
 * Sets up the initial structure of the spreadsheet (Headers and Rows).
 */
function setupSpreadsheetStructure() {
    const container = document.getElementById('spreadsheet-container');
    if (!container) return;

    // 1. Setup Headers (A, B, C...)
    let headerRow = container.querySelector('#spreadsheet-container thead tr');
    if (!headerRow) {
        console.error("No se encontró la fila de encabezado.");
        return;
    }

    const maxCols = 10; // A to J
    for (let i = 0; i < maxCols; i++) {
        const colName = String.fromCharCode(65 + i); // ASCII A=65
        let th = document.querySelector(`th[data-col-name="${colName}"]`);
        if (!th) {
            th = document.createElement('th');
            th.setAttribute('data-col-name', colName);
            headerRow.appendChild(th);
        } else {
             // Asegurarse de que el atributo exista si se regenera
             th.setAttribute('data-col-name', colName);
        }
    }

    // 2. Setup Rows (1 to 20)
    const tbody = container.querySelector('#spreadsheet-container tbody');
    if (!tbody) return;

    for (let r = 1; r <= 20; r++) {
        let newRow = document.createElement('tr');
        newRow.id = `row-header-${r}`;

        // Celda de índice de fila
        let indexCell = document.createElement('td');
        indexCell.className = 'row-index';
        indexCell.textContent = r;
        newRow.appendChild(indexCell);

        // Celdas de datos (A a J)
        for (let c = 0; c < maxCols; c++) {
            const colName = String.fromCharCode(65 + c);
            let cell = document.createElement('td');
            cell.setAttribute('data-row', r);
            cell.setAttribute('data-col', colName);
            cell.contentEditable = 'true';
            newRow.appendChild(cell);
        }
        tbody.appendChild(newRow);
    }

    // Inicializar el estado de los botones
    updateControlsState();
}


