/**
 * Inicializa la estructura completa de la hoja de cálculo (20 filas, 11 columnas).
 * @param {HTMLElement} container - El contenedor principal de la hoja de cálculo.
 */
function initializeSpreadsheet(container) {
    const table = container.querySelector('table');
    if (!table) return;

    // 1. Inicializar Encabezados (A-J)
    const headerRow = table.querySelector('.column-headers');
    if (!headerRow) {
        console.error("No se encontró la fila de encabezados.");
        return;
    }

    // Limpiar headers existentes para asegurar que solo estén A-J
    Array.from(headerRow.children).forEach((th, index) => {
        if (index > 0 && th.dataset.colName) { // Excluir la primera celda vacía
            const colName = th.dataset.colName;
            // Asegurarse de que el nombre de columna esté en mayúsculas y sea válido
            th.textContent = colName;
        } else if (index === 0) {
             // Mantener la primera celda vacía para los índices de fila
        }
    });

    const numRows = 20;
    const cols = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];

    // 2. Generar Filas (1 a 20)
    let tbody = table.querySelector('tbody');
    if (!tbody) {
        tbody = document.createElement('tbody');
        table.appendChild(tbody);
    } else {
        tbody.innerHTML = ''; // Limpiar contenido previo si se reinicializa
    }

    for (let i = 1; i <= numRows; i++) {
        const row = document.createElement('tr');
        row.id = `row-header-${i}`;

        // Celda de índice de fila
        const indexCell = document.createElement('td');
        indexCell.className = 'row-index';
        indexCell.textContent = i;
        row.appendChild(indexCell);

        // Celdas de datos (A a J)
        cols.forEach(col => {
            const cell = document.createElement('td');
            cell.setAttribute('data-row', i);
            cell.setAttribute('data-col', col);
            cell.contentEditable = 'true';
            // Añadir un evento de cambio para manejar la selección y el estado
            cell.addEventListener('input', handleCellInput); 
            row.appendChild(cell);
        });

        tbody.appendChild(row);
    }
    updateControlsState();
}


