function hideColumn(columnIndex) {
    const container = document.getElementById('spreadsheet-container');
    if (!container) return;

    // 1. Hide the column header (<th>)
    const headerElement = container.querySelector(`.col-header[data-column="${columnIndex}"]`);
    if (headerElement) {
        headerElement.classList.add('hidden-column');
    }

    // 2. Iterate over all rows and hide the corresponding data cell (<td>)
    const allRows = container.querySelectorAll('tbody tr');
    allRows.forEach(row => {
        const cells = row.querySelectorAll('td');
        if (cells.length > columnIndex) {
            const targetCell = cells[columnIndex];
            targetCell.classList.add('hidden-column');
        }
    });

    // 3. Update the state/UI if necessary (e.g., button states, internal tracking)
    console.log(`Column ${columnIndex} hidden successfully.`);
}
