    // 2. Hide the header cell (<th>) for the specified column
    const headerCell = document.querySelector(`th[data-column="${colLetter}"]`);
    if (headerCell) {
        headerCell.classList.add('hidden-column');
    }

    // 3. Update visibility state and UI controls
    document.getElementById('col-visibility-status').textContent = `Columna ${colLetter} oculta`;
    updateColumnControls(colIndex, false);
}
