 */
const ROWS = 20;
const COLS = 10; // A to J
let spreadsheetContainer = document.getElementById('spreadsheet-container');
let cells = []; // Array para almacenar todas las referencias a celdas de datos

// --- UTILITY FUNCTIONS ---

/**
 * Genera la estructura inicial de la hoja de cálculo (filas y encabezados).
 */
function initializeSpreadsheet() {
    const tbody = spreadsheetContainer.querySelector('tbody');
    if (!tbody) return;

    // Limpiar contenido previo si existe
    tbody.innerHTML = '';
    cells = [];

    for (let r = 1; r <= ROWS; r++) {
        const row = document.createElement('tr');
        row.id = `row-header-${r}`; // ID para la fila completa

        // Celda de índice de fila (A la izquierda)
        const indexCell = document.createElement('td');
        indexCell.className = 'row-index';
        indexCell.textContent = r;
        row.appendChild(indexCell);

        for (let c = 0; c < COLS; c++) {
            const colName = String.fromCharCode(65 + c); // A, B, C...
            const cell = document.createElement('td');
            cell.setAttribute('data-row', r);
            cell.setAttribute('data-col', colName);
            cell.contentEditable = 'true';
            // Añadir un evento de input para que los cambios se detecten inmediatamente (aunque el guardado es al unload)
            cell.addEventListener('input', handleCellInput); 
            row.appendChild(cell);
            cells.push(cell); // Almacenar la referencia a la celda
        }
        tbody.appendChild(row);
    }

    // Asegurarse de que los botones estén habilitados si hay contenido inicial (aunque en este caso, siempre habrá 20 filas)
    updateControlStates();
}


