function evaluateFormula(cellElement) {
    let content = cellElement.textContent.trim();
    if (!content || !content.startsWith('=')) {
        return { result: content, isFormula: false };
    }

    // 1. Extract the formula string (everything after '=')
    const formulaString = content.substring(1);

    try {
        // 2. Replace cell references (A1, B2, etc.) with actual values
        let evaluatedFormula = formulaString;

        // Regex to find standard Excel-like references: [A-Z]+[0-9]+
        const cellRefRegex = /([A-Z]{1,3})([0-9]+)/g;

        evaluatedFormula = evaluatedFormula.replace(cellRefRegex, (match, colStr, rowNum) => {
            // Convert column letters to index (A=1, B=2, ...)
            let colIndex = 0;
            for (let i = 0; i < colStr.length; i++) {
                colIndex += (colStr.charCodeAt(i) - 'A'.charCodeAt(i - 1));
            }
            // Adjusting for 1-based indexing used in the spreadsheet structure
            const actualColIndex = colStr.toUpperCase().split('').reduce((acc, char) => acc * 26 + (char.charCodeAt(0) - 'A'.charCodeAt(0) + 1), 0);

            // Get the cell element corresponding to this reference
            let targetCell = document.querySelector(`[data-col="${actualColIndex}"][data-row="${rowNum}"]`);

            if (targetCell && targetCell.textContent.trim() !== '') {
                const value = parseFloat(targetCell.textContent);
                return isNaN(value) ? `'${targetCell.textContent}`.replace(/'/g, "''") : value; // Handle text vs number
            } else {
                // If cell reference doesn't exist or is empty, treat it as 0 for calculation safety
                return '0';
            }
        });

        // 3. Evaluate the formula string using a safe context (eval)
        // Note: Using eval() here is necessary for dynamic formula evaluation in vanilla JS, 
        // but requires careful sanitization/context management in production apps.
        const result = eval(evaluatedFormula);

        if (isNaN(result)) {
             return { result: 'Error', isFormula: true };
        }

        // Return the calculated number and flag it as a formula
        return { 
            result: parseFloat(result.toFixed(2)), // Limit decimals for display consistency
            isFormula: true,
            formulaString: content // Keep original string for display/reference
        };

    } catch (e) {
        console.error("Error evaluating formula:", e);
        return { result: 'ERROR', isFormula: false };
    }
}
