function evaluateFormula(formula) {
    // 1. Clean up formula string (remove spaces, standardize separators)
    let cleanFormula = formula.toUpperCase().replace(/\s/g, '');

    // Check if it's a simple arithmetic operation first
    if (!cleanFormula.includes('(')) {
        try {
            // Simple math evaluation: A1-B1, A1*B1, etc.
            // We need to replace cell references (like A1) with their actual values.
            let expression = cleanFormula;
            const cells = document.querySelectorAll('#spreadsheet-container td[contenteditable="true"]');

            for (const cell of cells) {
                const content = cell.getAttribute('data-row') + '-' + cell.getAttribute('data-col').toUpperCase();
                // Regex to find references like A1, B2, etc.
                expression = expression.replace(new RegExp(`(${cell.getAttribute('data-col')}\\d+)`, 'g'), (match) => {
                    const value = parseFloat(cell.innerText);
                    return isNaN(value) ? '0' : value; // Treat non-numeric references as 0 for calculation safety
                });
            }

            // Use Function constructor for safe evaluation of mathematical expressions
            try {
                return new Function('return ' + expression)();
            } catch (e) {
                console.error("Error evaluating simple formula:", e);
                return "ERROR";
            }
        } catch (e) {
            return "ERROR";
        }
    }

    // 2. Handle complex functions like SUMA(A1:A3) or SUMA(A1;B2;C3)
