        let formulaName = cleanFormula.substring(0, 4); // e.g., SUMA
        let argsString = cleanFormula.substring(formulaName.length + 1, cleanFormula.length - 1);

        if (formulaName === 'SUMA') {
            // Check for range format A1:B2 or list format A1;B2;C3
            const parts = argsString.split(/([A-Z]\d+):?([A-Z]\d+)|([A-Z]\d+);/g).filter(p => p && p !== ':');

            let sum = 0;
            for (const part of parts) {
                if (!part) continue;

                // Check if it's a range (e.g., A1:B2) - this is complex to parse perfectly without a library,
                // so we focus on the common case: single cell references or comma/semicolon separated lists.

                let matches = part.match(/([A-Z]\d+):?([A-Z]\d+)/);
                if (matches) {
                    const startRef = matches[1];
                    const endRef = matches[2] || startRef; // If only one reference is given, assume it's a single cell.

                    // Simple range handling: iterate through all cells in the bounding box defined by start and end references
                    let startCol = getColumnIndex(startRef);
                    let startRow = parseInt(startRef.substring(1));
                    let endCol = getColumnIndex(endRef);
                    let endRow = parseInt(endRef.substring(1));

                    if (isNaN(startCol) || isNaN(startRow) || isNaN(endCol) || isNaN(endRow)) return "ERROR";

                    for (let r = startRow; r <= endRow; r++) {
                        for (let c = Math.min(startCol, endCol); c <= Math.max(startCol, endCol); c++) {
                            const cellElement = document.querySelector(`[data-row="${r}"][data-col="${getColName(c)}"]`);
                            if (cellElement) {
                                const value = parseFloat(cellElement.innerText);
                                if (!isNaN(value)) {
                                    sum += value;
                                }
                            }
                        }
                    }
                } else {
                    // Single cell reference or list item (e.g., A1 or B2)
                    const ref = part.trim();
                    if (ref) {
                         let colName = getColName(getColumnIndex(ref));
                         let rowNum = parseInt(ref.substring(1));

                         const cellElement = document.querySelector(`[data-row="${rowNum}"][data-col="${colName}"]`);
                         if (cellElement) {
                             const value = parseFloat(cellElement.innerText);
                             if (!isNaN(value)) {
                                 sum += value;
                             }
                         }
                    }
                }
            }
            return sum;

        } else if (formulaName === 'SUM') {
             // Handle English SUM function if needed, though requirement specifies Spanish.
             // For simplicity and adherence to R3, we assume only SUMA is used.
             return "ERROR";
        }
    } catch (e) {
        console.error("Error evaluating formula:", e);
        return "ERROR";
    }

    return null; // No recognized function or error occurred
}

// Helper functions for coordinate parsing (assuming A=0, B=1, etc.)
function getColumnIndex(colName) {
    if (!colName || typeof colName !== 'string') return -1;
    let index = 0;
    for (let i = 0; i < colName.length; i++) {
        index = index * 26 + (colName.charCodeAt(i) - 'A'.charCodeAt(0) + 1);
    }
    return index - 1; // Convert 1-based calculation to 0-based array index if needed, but here we use it for math logic.
}

function getColName(index) {
    if (index < 0 || index >= 26) return null;
    let name = '';
    while (index >= 0) {
        name = String.fromCharCode('A'.charCodeAt(0) + (index % 26)) + name;
        index = Math.floor(index / 26) - 1;
    }
    return name;
}
