document.addEventListener('DOMContentLoaded', () => {
    const spreadsheetContainer = document.getElementById('spreadsheet-container');
    const rowsCount = 20;
    const colsNames = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];

    // --- Initialization of Spreadsheet Grid ---
    let tableBody = spreadsheetContainer.querySelector('tbody');
    tableBody.innerHTML = ''; // Clear existing content

    for (let i = 1; i <= rowsCount; i++) {
        const row = document.createElement('tr');
        row.id = `row-header-${i}`;
        // Row Index Cell
        let indexCell = document.createElement('td');
        indexCell.className = 'row-index';
        indexCell.textContent = i;
        row.appendChild(indexCell);

        // Data Cells (A to J)
        for (let j = 0; j < colsNames.length; j++) {
            const colName = colsNames[j];
            let cell = document.createElement('td');
            cell.setAttribute('data-row', i);
            cell.setAttribute('data-col', colName);
            cell.contentEditable = 'true';
            cell.addEventListener('input', handleCellInput);
            cell.addEventListener('blur', handleCellBlur); // Use blur to trigger calculations after input stops
            row.appendChild(cell);
        }
        tableBody.appendChild(row);
    }

    // --- Event Listeners for Controls ---
    document.getElementById('btn-clear-data').addEventListener('click', clearSelectedData);
    document.getElementById('colorPicker').addEventListener('input', (e) => { /* No action needed here */ });
    document.getElementById('btn-apply-color').addEventListener('click', applyBackground_color);
    document.getElementById('btn-hide-row').addEventListener('click', () => hideSelectedRow());
    document.getElementById('btn-show-row').addEventListener('click', () => showSelectedRow());
    document.getElementById('btn-delete-row').addEventListener('click', deleteSelectedRow);
    document.getElementById('btn-clear-column').addEventListener('click', clearSelectedColumn);
    document.getElementById('btn-hide-col').addEventListener('click', () => hideSelectedColumn());
    document.getElementById('btn-show-col').addEventListener('click', () => showSelectedColumn());

    // Initial setup for controls state (assuming some initial logic exists)
    updateControlStates(); 
});
